//! 📜 Playbook-play app — textual document grammar surface (constitutional: dsl).
//!
//! `PlaybookSpec`'s `store::DocumentDsl` impl is generated by the `dsl::DslDocument` derive on its
//! definition in the kernel crate `s/kernel/playbook/rs` — this crate only re-exposes the
//! parse/print entry points under the app's own constitutional `dsl` slot.

use playbook::PlaybookSpec;

/// 📖 Parses `.playbook` DSL text into a `PlaybookSpec`.
pub fn parse_dsl(text: &str) -> Result<PlaybookSpec, store::TextError> {
    <PlaybookSpec as store::DocumentDsl>::parse_dsl(text)
}

/// 🖨️ Prints a `PlaybookSpec` back to `.playbook` DSL text.
pub fn print_dsl(document: &PlaybookSpec) -> String {
    store::DocumentDsl::print_dsl(document)
}

//#region 🧪Tests
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dsl_round_trips_the_empty_projection() {
        let document = playbook::empty_playbook_projection();
        let text = print_dsl(&document);
        assert_eq!(parse_dsl(&text).expect("parse"), document);
    }
}
//#endregion 🧪Tests
